import numpy as np

# Hypothesis: empty cells (0 in metagrid) become 3s
# Output metagrid:
meta = [
    [2, 2, 2, 2],
    [2, 3, 3, 3],  # filled empty with 3
    [3, 3, 3, 3],
    [2, 3, 2, 2]   # filled empty with 3
]

# Expand to 19x19
def get_block_pattern(value):
    if value == 2:
        return np.array([
            [2, 2, 2, 2],
            [2, 0, 0, 0],
            [2, 0, 0, 2],
            [2, 0, 2, 2]
        ])
    elif value == 3:
        return np.array([
            [3, 3, 3, 3],
            [3, 3, 3, 3],
            [3, 3, 3, 3],
            [3, 3, 3, 3]
        ])
    else:
        return np.zeros((4, 4), dtype=int)

output_grid = np.zeros((19, 19), dtype=int)
block_row_starts = [0, 5, 10, 15]
block_col_starts = [0, 5, 10, 15]

for i in range(4):
    for j in range(4):
        pattern = get_block_pattern(meta[i][j])
        for r in range(4):
            for c in range(4):
                output_grid[block_row_starts[i] + r, block_col_starts[j] + c] = pattern[r, c]

print("Output grid:")
for row in output_grid:
    print(*row)

